// Checkout.test.tsx
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mocks - because we need to control what's really happening
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();
const mockOnComplete = vi.fn();
const mockOnCancel = vi.fn();

const mockCartItems = [
  { id: '1', name: 'Widget', price: 29.99 },
  { id: '2', name: 'Gadget', price: 49.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: mockCartItems,
    total: 79.98,
    clearCart: mockClearCart
  })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  // HAPPY PATH - People need to know what's really happening
  describe('Complete Checkout Flow', () => {
    it('completes full checkout journey from shipping to confirmation', async () => {
      const user = userEvent.setup();
      render(<Checkout onComplete={mockOnComplete} />);

      // Arrange: Fill shipping
      await user.type(screen.getByLabelText(/street address/i), '123 Ankh Street');
      await user.type(screen.getByLabelText(/city/i), 'Ankh-Morpork');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');

      // Act: Proceed to payment
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Assert: Payment form visible
      expect(screen.getByRole('form', { name: /payment information/i })).toBeInTheDocument();

      // Fill payment
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Sam Vimes');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/widget/i)).toBeInTheDocument();
      expect(screen.getByText(/\$79\.98/)).toBeInTheDocument();

      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText('ORD-12345')).toBeInTheDocument();
      expect(mockOnComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  // VALIDATION - That's not an answer. That's just words in answer-shaped order.
  describe('Form Validation', () => {
    it('displays inline errors for empty shipping fields', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip/i), 'ABCDE');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  // EDGE CASES - Would you like to comment on the bug?
  describe('Edge Cases', () => {
    it('shows empty cart message when no items', () => {
      vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout onCancel={mockOnCancel} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });

    it('handles payment failure gracefully', async () => {
      mockProcessPayment.mockRejectedValue(new Error('Card declined'));
      const user = userEvent.setup();
      // ... navigate to review step ...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);
    });
  });

  // ACCESSIBILITY - I think our readers would be very interested in this
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
